    @Test
    public void isLegacyAbsolutePath_returnsFalseWhenRequiredInputIsMissing() {
        ST_Box boundary = new ST_Box(0, 0, 210, 297);
        List<PathPoint> points = Collections.singletonList(new PathPoint("M", 1000, 1000, 0, 0, 0, 0));
        ST_Array ctm = new ST_Array(1, 0, 0, 1, 10000, 10000);

        assertFalse(PointUtil.isLegacyAbsolutePath(210, 297, null, points, true, ctm));
        assertFalse(PointUtil.isLegacyAbsolutePath(210, 297, boundary, points, false, ctm));
        assertFalse(PointUtil.isLegacyAbsolutePath(210, 297, boundary, points, true, null));
        assertFalse(PointUtil.isLegacyAbsolutePath(210, 297, boundary, null, true, ctm));
        assertFalse(PointUtil.isLegacyAbsolutePath(210, 297, boundary,
                Collections.<PathPoint>emptyList(), true, ctm));
    }

