        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.singletonList(transform), null, null, false, null, false, 1);

        assertEquals(2, points.size());
        assertEquals("G0", points.get(0).getGlyph());
        assertEquals("G1", points.get(1).getGlyph());
    }

    @Test
    public void calPdfTextCoordinateWithTransforms_appendsExtraGlyphsToLastPoint() {
        TextCode textCode = new TextCode();
        textCode.setContent("A");
        textCode.setCoordinate(0d, 0d);

        CT_CGTransform transform = new CT_CGTransform();
        transform.setCodePosition(0);
        transform.setCodeCount(3);
        transform.setGlyphCount(3);
        transform.setGlyphs(new ST_Array("G0", "G1", "G2"));

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.singletonList(transform), null, null, false, null, false, 1);

        assertEquals(1, points.size());
        assertEquals("G0 G1 G2", points.get(0).getGlyph());
    }

    @Test
    public void calPdfTextCoordinateWithTransforms_appliesCtmTranslation() {
        TextCode textCode = new TextCode();
        textCode.setContent("AB");
        textCode.setCoordinate(10d, 20d);
        textCode.setDeltaX(1d);
        textCode.setDeltaY(0d);
        ST_Array ctm = new ST_Array(1, 0, 0, 1, 5, 7);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.<CT_CGTransform>emptyList(), null, null, true, ctm, false, 1);

        assertEquals(2, points.size());
        assertEquals(42.5197, points.get(0).getX(), EPS);
        assertEquals(76.5354, points.get(0).getY(), EPS);
        assertEquals(45.3543, points.get(1).getX(), EPS);
        assertEquals(76.5354, points.get(1).getY(), EPS);
    }

    @Test
    public void calPdfTextCoordinateWithTransforms_elevenArgumentOverloadUsesUnitScale() {
        TextCode textCode = new TextCode();
        textCode.setContent("A");
        textCode.setCoordinate(10d, 20d);

        List<TextCodePoint> points = PointUtil.calPdfTextCoordinate(
                100, 200, null, 12f, Collections.singletonList(textCode),
                Collections.<CT_CGTransform>emptyList(), null, null, false, null, false);

        assertEquals(1, points.size());
        assertEquals(28.3465, points.get(0).getX(), EPS);
        assertEquals(56.6929, points.get(0).getY(), EPS);
    }
}
